SELECT * FROM vw_sales_daily
WHERE sales_date BETWEEN #{startDate} AND #{endDate}
ORDER BY sales_date

SELECT COALESCE(SUM(CASE WHEN order_type_code = 'EAT_IN' THEN order_count ELSE 0 END), 0) AS eatIn,
       COALESCE(SUM(CASE WHEN order_type_code = 'TAKE_OUT' THEN order_count ELSE 0 END), 0) AS takeOut
FROM vw_order_status_summary WHERE order_date = #{date}
